export const getCityBySlug = (slug) => cities.find((c) => c.slug === slug);
export const getCountryBySlug = (slug) => cities.find((c) => c.countrySlug === slug);

export const getScoreColor = (score) => {
  if (score >= 75) return "#10b981";
  if (score >= 50) return "#f59e0b";
  return "#ef4444";
};

export const getScoreLabel = (score) => {
  if (score >= 80) return "Excellent";
  if (score >= 65) return "Good";
  if (score >= 50) return "Moderate";
  if (score >= 35) return "Below Average";
  return "Poor";
};

export const continents = ["All", "Europe", "Asia", "North America", "South America", "Africa", "Oceania"];